arguments.command:
bash -lc 'python - << "PY"
p = "src/p_lx_elf.cpp"
with open(p, "r") as f:
    s = f.read()
marker = "e_phoff = get_te64(&ehdri.e_phoff);"
pos = s.find(marker)
if pos == -1:
    print("marker not found");
    raise SystemExit(1)
end = s.find("
", pos) + 1
insert = "
    if (e_phoff > file_size) {
        e_phoff = 0;
        e_shoff = 0;
        sz_phdrs = 0;
        return;
    }
"
s = s[:end] + insert + s[end:]
with open(p, "w") as f:
    f.write(s)
print("patched")
PY'

bash -lc '
awk \'{ if (!patched && $0 ~ /e_phoff = get_te64\\(&ehdri.e_phoff\\);/) { print $0; print "\tif (e_phoff > file_size) {"; print "\t\te_phoff = 0;"; print "\t\te_shoff = 0;"; print "\t\tsz_phdrs = 0;"; print "\t\treturn;"; print "\t}"; patched=1; next } { print } }\' src/p_lx_elf.cpp > /tmp/patch1; mv /tmp/patch1 src/p_lx_elf.cpp;
awk \'{ if ($0 ~ /e_shoff = get_te64\\(&ehdri.e_shoff\\);/) { print $0; print "\tif (e_shoff > file_size) {"; print "\t\te_shoff = 0;"; print "\t\tsz_phdrs = 0;"; print "\t\treturn;"; print "\t}"; next } { print } }\' src/p_lx_elf.cpp > /tmp/patch2; mv /tmp/patch2 src/p_lx_elf.cpp'
